import gurobipy as gp
from gurobipy import GRB
products = []
value = {}
weight = {}
capacity = None
for rec in LEGACY_RECORDS:
    if rec['source'] == 'products.csv':
        v = rec['values']
        pname = v['ProductName']
        products.append(pname)
        try:
            value[pname] = int(v['Value'])
        except Exception:
            raise ValueError(f'Missing or invalid Value for {pname}')
        try:
            weight[pname] = int(v['Weight'])
        except Exception:
            raise ValueError(f'Missing or invalid Weight for {pname}')
    elif rec['source'] == 'capacity.csv':
        v = rec['values']
        if 'Capacity' in v:
            capacity = int(v['Capacity'])
if capacity is None:
    raise ValueError('Missing total capacity in LEGACY_RECORDS')
for pname in products:
    if pname not in value or pname not in weight:
        raise ValueError(f'Missing value or weight for {pname}')
m = gp.Model('vehicle_inventory')
x = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((value[i] * x[i] for i in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[i] * x[i] for i in products)) <= capacity, name='total_weight')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')